  {#if data.accounts.length}<section class="section-block investment-section"><div class="section-heading"><div><p class="eyebrow">New transfer</p><h2>Deposit or withdraw capital</h2><p class="section-caption">Use a personal wallet in the same currency. Transfers update wallet balances but are not income or spending.</p></div></div><form method="POST" action="?/cashMovement" class="feature-form investment-form" use:enhance={handleInvestmentSubmit}><label>Investment account<select name="investment_account_id" required>{#each data.accounts as account}<option value={account.id}>{account.name} · {account.currency === 'USD' ? 'USD' : 'ZiG'}</option>{/each}</select></label><label>Movement<select name="kind"><option value="deposit">Deposit to investment</option><option value="withdrawal">Withdraw to personal wallet</option></select></label><label>Personal wallet<select name="wallet_account_id" required>{#each data.wallets as wallet}<option value={wallet.id}>{wallet.currency === 'USD' ? 'USD' : 'ZiG'} · {wallet.wallet_group?.name ?? 'Wallet'}{wallet.channel ? ` · ${wallet.channel}` : ''}</option>{/each}</select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" required/></label><label>Date<input name="occurred_on" type="date" value={data.today} required/></label><label class="form-wide">Note<input name="description" maxlength="240" placeholder="Optional transfer note"/></label><div class="form-wide form-footer"><p>Withdrawals cannot exceed the recorded investment balance.</p><button class="primary-button" type="submit"><ArrowLeftRight size={16}/> Record transfer</button></div></form></section>
    <section class="section-block investment-section"><div class="section-heading"><div><p class="eyebrow">Transfer history</p><h2>Deposits and withdrawals</h2></div></div><div class="investment-activity-list">{#each data.movements as movement}<div class="investment-activity-row"><span class="investment-activity-icon">{#if movement.kind === 'deposit'}<ArrowUpRight size={16}/>{:else}<ArrowDownLeft size={16}/>{/if}</span><div class="investment-activity-main"><strong>{movement.kind === 'deposit' ? 'Deposit to' : 'Withdrawal from'} {accountName(movement.investment_account_id)}</strong><span>{new Date(movement.occurred_at).toLocaleDateString()} · {movement.description || 'Investment transfer'}</span></div><strong class="investment-activity-amount">{money(movement.amount, accountCurrency(movement.investment_account_id))}</strong></div>{:else}<p class="investment-table-empty">No investment transfers yet.</p>{/each}</div></section>
  {:else}<section class="investment-empty"><span class="investment-icon"><ArrowLeftRight size={20}/></span><div><h2>Create an investment account before transferring capital</h2><p>Set up the investment account first so deposits and withdrawals have a destination.</p><a class="primary-button compact-button" href="/investments/accounts">Open Accounts</a></div></section>{/if}
